package com.hmdp.ai.infrastructure.persistence;
import com.fasterxml.jackson.databind.ObjectMapper;import com.hmdp.ai.domain.mcp.*;import com.hmdp.ai.shared.id.AiIdGenerator;import com.hmdp.ai.shared.json.ContentHashService;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;import org.springframework.transaction.annotation.Transactional;import java.sql.*;import java.time.Instant;import java.util.*;
@Repository public class JdbcMcpRepository implements McpRepository {private final JdbcTemplate jdbc;private final ObjectMapper mapper;private final AiIdGenerator ids;private final ContentHashService hashes;public JdbcMcpRepository(JdbcTemplate jdbc,ObjectMapper mapper,AiIdGenerator ids,ContentHashService hashes){this.jdbc=jdbc;this.mapper=mapper;this.ids=ids;this.hashes=hashes;}public McpServer create(McpServer s,String actor){jdbc.update("insert into ai_mcp_server (id,tenant_id,workspace_id,code,name,namespace,transport,endpoint_or_command,secret_ref,allowed_tools_json,timeout_ms,allow_private_network,health_status,enabled,status,created_by,updated_by) values (?,?,?,?,?,?,?,?,?,?,?,?,'UNKNOWN',?,'ACTIVE',?,?)",s.getId(),s.getTenantId(),s.getWorkspaceId(),s.getCode(),s.getName(),s.getNamespace(),s.getTransport().name(),s.getEndpoint(),s.getSecretRef(),s.getAllowedToolsJson(),s.getTimeoutMs(),s.isAllowPrivateNetwork(),s.isEnabled(),actor,actor);return s;}public List<McpServer>findAll(String t,String w){return jdbc.query(select()+" where tenant_id=? and workspace_id=? and deleted=0 order by updated_at desc,id",(rs,row)->map(rs),t,w);}public Optional<McpServer>find(String t,String w,String id){return jdbc.query(select()+" where tenant_id=? and workspace_id=? and id=? and deleted=0",(rs,row)->map(rs),t,w,id).stream().findFirst();}public void updateHealth(String t,String w,String id,String health,String actor){jdbc.update("update ai_mcp_server set health_status=?,updated_by=? where tenant_id=? and workspace_id=? and id=? and deleted=0",health,actor,t,w,id);}
    @Transactional public int syncTools(McpServer s,List<McpToolDescriptor>tools,String actor){Set<String>allowed=allowed(s.getAllowedToolsJson());int count=0;for(McpToolDescriptor d:tools){if(!allowed.isEmpty()&&!allowed.contains(d.getName()))continue;Integer existing=jdbc.queryForObject("select count(*) from ai_mcp_tool_binding where mcp_server_id=? and remote_tool_name=? and deleted=0",Integer.class,s.getId(),d.getName());if(existing!=null&&existing>0){count++;continue;}String toolId=ids.nextId(),versionId=ids.nextId(),bindingId=ids.nextId(),code="mcp:"+s.getCode()+":"+d.getName().replaceAll("[^A-Za-z0-9_.-]","-");String input=json(d.getInputSchema()),configuration=json(mapper.createObjectNode().put("serverId",s.getId()).put("toolName",d.getName()));String hash=hashes.sha256(input+configuration);jdbc.update("insert into ai_tool (id,tenant_id,workspace_id,code,name,description,latest_version,status,created_by,updated_by) values (?,?,?,?,?,?,1,'ACTIVE',?,?)",toolId,s.getTenantId(),s.getWorkspaceId(),code,d.getName(),d.getDescription(),actor,actor);jdbc.update("insert into ai_tool_version (id,tenant_id,workspace_id,tool_id,version,name,description,protocol,input_schema,output_schema,risk_level,side_effect,idempotent,timeout_ms,retry_policy_json,required_permissions_json,configuration_json,enabled,status,content_hash,change_note,published_at,published_by,created_by,updated_by) values (?,?,?,?,1,?,?,'MCP',?,?,'LOW',0,0,?,'{\"maxAttempts\":1}','[\"AGENT_RUN\"]',?,1,'PUBLISHED',?,'MCP discovery sync',?,?,?,?)",versionId,s.getTenantId(),s.getWorkspaceId(),toolId,d.getName(),d.getDescription(),input,"{}",s.getTimeoutMs(),configuration,hash,Timestamp.from(Instant.now()),actor,actor,actor);jdbc.update("insert into ai_mcp_tool_binding (id,tenant_id,workspace_id,mcp_server_id,remote_tool_name,tool_id,tool_version_id,remote_schema_hash,status,created_by,updated_by) values (?,?,?,?,?,?,?,?,'ACTIVE',?,?)",bindingId,s.getTenantId(),s.getWorkspaceId(),s.getId(),d.getName(),toolId,versionId,hash,actor,actor);count++;}jdbc.update("update ai_mcp_server set last_sync_at=?,health_status='UP',updated_by=? where id=? and deleted=0",Timestamp.from(Instant.now()),actor,s.getId());return count;}
    private String select(){return "select id,tenant_id,workspace_id,code,name,namespace,transport,endpoint_or_command,secret_ref,allowed_tools_json,timeout_ms,allow_private_network,health_status,enabled,last_sync_at,status from ai_mcp_server";}private McpServer map(ResultSet r)throws SQLException{return new McpServer(r.getString("id"),r.getString("tenant_id"),r.getString("workspace_id"),r.getString("code"),r.getString("name"),r.getString("namespace"),McpTransport.valueOf(r.getString("transport")),r.getString("endpoint_or_command"),r.getString("secret_ref"),r.getString("allowed_tools_json"),r.getInt("timeout_ms"),r.getBoolean("allow_private_network"),r.getString("health_status"),r.getBoolean("enabled"),JdbcTime.instant(r.getTimestamp("last_sync_at")),r.getString("status"));}private Set<String>allowed(String json){try{Set<String>s=new LinkedHashSet<>();for(com.fasterxml.jackson.databind.JsonNode n:mapper.readTree(json))s.add(n.asText());return s;}catch(Exception e){throw new IllegalStateException("stored MCP allow-list is invalid",e);}}private String json(Object v){try{return mapper.writeValueAsString(v);}catch(Exception e){throw new IllegalStateException("MCP tool schema serialization failed",e);}}
}
